(async()=>{try{const res=await fetch('/productivity-2025.json');if(!res.ok)throw Error('자료를 불러오지 못했습니다.');const d=await res.json(),$=id=>document.getElementById(id);const el=(tag,text)=>{const n=document.createElement(tag);n.textContent=text;return n};function row(target,values){const tr=document.createElement('tr');values.forEach(v=>tr.append(el('td',v)));target.append(tr)}function render(){const q=$('search').value.trim(),c=$('category').value;const rows=d.awards.filter(r=>r.region.includes(q)&&(!c||r.category===c));$('awards').replaceChildren();rows.forEach(r=>row($('awards'),[r.region,r.category,r.awarding_authority]));$('count').textContent=rows.length+'곳 표시';$('cases').replaceChildren();d.policy_cases.filter(r=>!$('field').value||r.field===$('field').value).forEach(r=>{const a=document.createElement('article');a.append(el('small',r.field+' · '+r.category),el('h3',r.region),el('p',r.title));$('cases').append(a)})}['search','category','field'].forEach(id=>$(id).addEventListener('input',render));d.type_comparisons.forEach(r=>row($('comparison'),[r.indicator,...[r.city,r.autonomous_district,r.county,r.reported_national_average].map(v=>v.toFixed(2)+'%')]));d.indicators.forEach(r=>row($('metrics'),[r.field,r.label,r.max_points.toFixed(2)]));d.limitations.forEach(t=>$('limits').append(el('li',t)));$('rounding').textContent=d.rounding_note;$('ask').onsubmit=e=>{e.preventDefault();const q=$('question').value.trim();if(/순위|점수|꼴찌|하위/.test(q)){$('answer').textContent='전체 점수표가 없어 종합순위와 개별 점수를 답할 수 없습니다. 보고서 별첨 1·4가 필요합니다.';return}const f=['경제','환경','문화','복지'].find(f=>q.includes(f));if(/사례|정책/.test(q)){$('field').value=f||'';render();$('answer').textContent='아래 정책 우수사례에 '+(f||'전체')+' 분야를 표시했습니다.';return}const c=['기량향상우수','기량향상장려','최우수','대상','우수','장려'].find(c=>q.includes(c));if(c){$('category').value=c;$('search').value='';render();$('answer').textContent=d.awards.filter(r=>r.category===c).map(r=>r.region).join(', ');return}if(/비교|인구|출산|고용/.test(q)){$('answer').textContent='아래 시·군·구 지표 비교 표에서 인구 증가율, 합계출산 증가율, 청년고용 증가율을 확인하세요.';return}$('answer').textContent='예: 대상 지자체는? / 환경 분야 우수사례 / 시·군·구 인구 비교. 정해진 질문 유형을 지원합니다.'};render()}catch(e){document.getElementById('message').textContent=e.message}})();